import { Faq } from "march/landing"
import { Button } from "march/ui"

// bilmece kutusu: soruya bas, cevap açılır; düğme kolay ve zor bilmeceler arasında geçer
const EASY = [
  { q: "Ağzı var, dili yok; durmadan akar. Nedir?", a: "Nehir 🌊" },
  { q: "Benim bir ağacım var, on iki dalı var. Nedir?", a: "Yıl ve aylar 📅" },
]
const HARD = [
  { q: "Ne kadar çok alırsan o kadar büyür. Nedir?", a: "Çukur 🕳️" },
  { q: "Adımı söylersen beni bozarsın. Ben neyim?", a: "Sessizlik 🤫" },
  { q: "Gece gelir, sabah gider; saymakla bitmez. Nedir?", a: "Yıldızlar ✨" },
]

export function RiddleFaq() {
  let $hard = false
  return <div sx={{ flex: "col", gap: 3 }}>
    <Button variant="secondary" on:click={() => $hard = !$hard}>{$hard ? "Kolaylara dön" : "Zor bilmeceler 🧠"}</Button>
    {() => { const hard = $hard; return <Faq items={hard ? HARD : EASY} multiple={hard} /> }}
  </div>
}

import { Faq } from "march/landing"
import { Button, toast } from "march/ui"
import { message } from "march/icons"

// bir kargo şirketinin yardım sayfası: solda başlık ve iletişim, sağda aranabilir sorular
export function CargoFaq() {
  return <Faq layout="split" search title="Kargonla ilgili sorular" lead="Yanıtı bulamazsan 7/24 canlı destekteyiz."
    contact={<Button variant="secondary" icon={message} on:click={() => toast("Canlı destek açılıyor")}>Canlı destek</Button>}
    labels={{ search: "Ara: takip, iade, ücret…", empty: "Bunu bulamadık. Canlı desteğe yaz.", count: (shown: number, total: number) => `${total} sorudan ${shown} eşleşme` }}
    items={[
      { q: "Kargomu nasıl takip ederim?", a: "Takip numaranı ana sayfadaki kutuya yaz ya da SMS'teki bağlantıya dokun.", keywords: "takip numara nerede" },
      { q: "Gönderim ücreti nasıl hesaplanır?", a: "Desi ve mesafeye göre; 2 desiye kadar şehir içi 89 TL.", keywords: "fiyat ücret desi" },
      { q: "Adresimde yoksam ne olur?", a: "Kurye bir not bırakır; paketi 3 gün içinde en yakın şubeden alabilirsin.", keywords: "teslim şube" },
      { q: "İade nasıl gönderilir?", a: "Satıcının iade kodunu şubede söyle; gönderim ücretsiz.", keywords: "iade geri" },
      { q: "Hafta sonu dağıtım var mı?", a: "Cumartesi büyükşehirlerde var, pazar yok.", keywords: "cumartesi pazar" },
    ]} />
}

import { Faq } from "march/landing"
import { Button, Card, Segmented, Toggle } from "march/ui"

// Faq'ın bütün özellikleri bir arada: sorular (q, a, keywords), düzen (layout), başlık (title), açıklama (lead),
// iletişim satırı (contact), arama (search), birden çok açık (multiple), kendi metinler (labels), eşleşme satırı
// (count), başlık girişi (reveal) ve sınıf (class)
const ITEMS = [
  { q: "Ücretsiz mi?", a: "Evet; Premium isteğe bağlı.", keywords: "fiyat para" },
  { q: "Telefonda çalışır mı?", a: "Telefonda da tarayıcıda da.", keywords: "mobil uygulama" },
  { q: "Etkinliğimi nasıl kurarım?", a: "Ne, nerede, ne zaman: birkaç adım." },
  { q: "İptal olursa ne olur?", a: "Katılanlara hemen bildirim gider.", keywords: "iade bilet" },
  { q: "Güvende miyim?", a: "Doğrulama, şikâyet ve engelleme her ekranda." },
]

export function FaqLab() {
  let $layout: "center" | "split" = "split"
  let $search = true
  let $multiple = false
  let $count = true
  let $asked = 0
  return <div sx={{ flex: "col", gap: 3 }}>
    <Card>
      <div sx={{ flex: ["row", "wrap"], gap: 3 }}>
        <Segmented aria-label="Düzen" options={[{ value: "center", label: "ortada" }, { value: "split", label: "iki sütun" }]} bind:value={$layout} />
        <Toggle label="Arama" bind:value={$search} />
        <Toggle label="Birden çok açık" bind:value={$multiple} />
        <Toggle label="Eşleşme satırı" bind:value={$count} />
      </div>
    </Card>
    {() => {
      // bu satırda okunan durumlar değişince sorular yeniden çizilir; başlık ve açıklama işlev, kendileri güncellenir
      const layout = $layout, search = $search, multiple = $multiple, count = $count
      return <Faq class="lab-faq" layout={layout} search={search} multiple={multiple} count={count} reveal="none"
        title={() => `Sık sorulanlar (${ITEMS.length})`} lead={() => `${$asked} kişi bize yazdı`}
        contact={<Button variant="secondary" on:click={() => $asked++}>Bize yaz</Button>}
        labels={{ search: "Soru ara", empty: "Hiçbir soru tutmadı.", count: (shown: number, total: number) => `${total} sorudan ${shown} tanesi` }}
        items={ITEMS} />
    }}
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { FaqLab } from "./FaqLab.tsx"

// FaqLab'in testleri: kaydedince Testler sekmesinde çalışır
test("beş soru; iki sütunda başlık ve iletişim satırı", () => {
  const s = renderTest(() => <FaqLab />)
  expect(s.all(".lab-faq .m-acc-item").length).toBe(5)
  expect(s.get(".lab-faq")?.classList.contains("m-faq-split")).toBe(true)
  expect(s.sees("Sık sorulanlar (5)")).toBe(true)
  expect(s.find("Bize yaz")).not.toBe(null)
})

test("arama listeyi daraltır ve sayıyı kendi metniyle yazar", async () => {
  const s = renderTest(() => <FaqLab />)
  await s.type("Soru ara", "iptal")
  await s.wait(() => s.sees("5 sorudan"))
  expect(s.all(".lab-faq .m-acc-item").length).toBeGreaterThan(0)
  expect(s.get(".lab-faq .m-acc-item")?.textContent).toContain("İptal olursa ne olur?")
  await s.type("Soru ara", "zzzqqq")
  await s.wait(() => s.sees("Hiçbir soru tutmadı."))
})

test("iletişim düğmesi açıklamayı günceller", async () => {
  const s = renderTest(() => <FaqLab />)
  await s.click("Bize yaz")
  expect(s.sees("1 kişi bize yazdı")).toBe(true)
})

test("ortada düzende başlık sütunu, arama kapanınca kutu gider", async () => {
  const s = renderTest(() => <FaqLab />)
  await s.click("ortada")
  await s.click("Arama")
  expect(s.get(".lab-faq")?.classList.contains("m-faq-split")).toBe(false)
  expect(s.get(".lab-faq .m-faq-search")).toBe(null)
})
